"""Essaint / Off Duty — the source of the second art direction."""
import pathlib,json,re,shutil
R=pathlib.Path(__file__).resolve().parents[1]
def write(path,s): (R/path).write_text(s,encoding='utf-8')
def section(name,body,settings=[],extra={}):write('theme/sections/'+name+'.liquid',body+'\n{% schema %}'+json.dumps({'name':name.replace('-',' ').title(),'settings':settings,'presets':[{'name':name.replace('-',' ').title()}],**extra})+'{% endschema %}')
section('header','''<div class="announcement" data-rotating><span>COMPLIMENTARY SHIPPING ON ORDERS OVER $100</span><span>CRAFTED IN LEBANON</span><span>7-DAY EASY EXCHANGES</span></div><header class="header"><nav aria-label="Main navigation"><a href="{{ routes.all_products_collection_url }}">SHOP ALL</a><a href="{{ routes.root_url }}#story">OUR WORLD</a></nav><a class="wordmark" href="{{ routes.root_url }}" aria-label="Essaint home"><img src="{{ 'essaint-logo.svg' | asset_url }}" width="212" height="78" alt="Essaint"></a><div class="header-actions"><span class="locale-label">LEBANON / {{ cart.currency.iso_code }}</span><button data-search aria-label="Search products">{% render 'icon', name: 'search' %}</button><button data-cart aria-label="Open shopping bag"><span class="bag-label">BAG</span> [<span data-count>{{ cart.item_count }}</span>]</button><button class="mobile-menu" data-menu aria-label="Open menu" aria-expanded="false"><span></span><span></span></button></div></header>''')
section('hero','''<section class="hero"><div class="hero-image"><video class="hero-video" data-hero-video data-mobile-poster="{{ 'hero-poster.jpg' | asset_url }}" data-desktop-poster="{{ 'hero-poster-desktop.jpg' | asset_url }}" width="576" height="1024" muted autoplay loop playsinline preload="none" poster="{{ 'hero-poster.jpg' | asset_url }}" aria-hidden="true"><source data-desktop-src="{{ 'hero-campaign-desktop.mp4' | asset_url }}" data-src="{{ 'hero-campaign.mp4' | asset_url }}" type="video/mp4"></video></div><div class="hero-slogan"><h1>{{ section.settings.heading | escape }} <span>{{ section.settings.subheading | escape }}</span></h1><div class="hero-glass-actions"><a class="hero-glass-button" href="{{ routes.all_products_collection_url }}">Discover</a><a class="hero-glass-button" href="{{ section.settings.seasonal_link | default: routes.all_products_collection_url }}">Fall/Winter 27</a></div></div></section><div class="category-rail"><a href="{{ routes.all_products_collection_url }}?filter.p.product_type=T-Shirts" data-category-link="tees"><span>01</span> Tops <b>↗</b></a><a href="{{ routes.all_products_collection_url }}" data-category-link="bottoms"><span>02</span> Bottoms <b>↗</b></a><a href="{{ routes.all_products_collection_url }}"><span>03</span> Full fit <b>↗</b></a></div>''',[{'type':'text','id':'heading','label':'Main headline','default':'Lebanese'},{'type':'text','id':'subheading','label':'Second line','default':'luxury wear'},{'type':'url','id':'seasonal_link','label':'Fall/Winter 27 link'}])
section('essentials','''<section class="section essentials bestsellers" id="essentials"><div class="section-heading"><div><p class="eyebrow">THE MOST LOVED</p><h2>Best sellers</h2></div><a class="text-link" href="{{ routes.all_products_collection_url }}">View all products <span aria-hidden="true">&#8599;</span></a></div><div class="product-grid" data-bestseller-grid>{% assign featured = section.settings.collection %}{% if featured != blank %}{% for product in featured.products limit: 6 %}{% render 'product-card', product: product, show_swatches: true %}{% endfor %}{% else %}{% assign bestseller_handles = 'skyline-striped-pants,linen-pants-unisex,over-size-t-shirt,milano-striped-pants-dropping-next-week,pinstriped-pants,tailored-pants' | split: ',' %}{% for handle in bestseller_handles %}{% assign product = all_products[handle] %}{% if product != blank %}{% render 'product-card', product: product, show_swatches: true %}{% endif %}{% endfor %}{% endif %}</div></section>''',[{'type':'collection','id':'collection','label':'Best sellers collection','info':'Choose a collection sorted by Best selling. Defaults to the verified best-selling snapshot.'}])
write('theme/snippets/product-card.liquid','''{% assign title_lower = product.title | downcase %}<article class="product-card" data-kind="{% if title_lower contains 't-shirt' %}tees{% else %}bottoms{% endif %}"><div class="product-media"><a class="product-photo" href="{{ product.url }}">{% if product.featured_image %}{{ product.featured_image | image_url: width: 900 | image_tag: loading: 'lazy', widths: '300,500,700,900', sizes: '(min-width: 900px) 25vw, 50vw' }}{% endif %}{% if product.images[1] %}{{ product.images[1] | image_url: width: 900 | image_tag: loading: 'lazy', class: 'alternate' }}{% endif %}<span class="badge">{% unless product.available %}SOLD OUT{% else %}{% if product.compare_at_price > product.price %}PRICE DROP{% endif %}{% endunless %}</span></a><button class="quick-add" data-product="{{ product.handle }}" aria-label="Choose options for {{ product.title | escape }}"><span>QUICK ADD</span><b>+</b></button></div><div class="product-meta"><a href="{{ product.url }}">{{ product.title }}</a><span>{{ product.price | money }}{% if product.compare_at_price > product.price %} <s>{{ product.compare_at_price | money }}</s>{% endif %}</span></div><p class="product-options">{{ product.options_with_values.first.values | join: ' / ' }}</p></article>''')
section('bundles','''<section class="bundle-section" id="bundles"><div class="bundle-intro"><p class="eyebrow">/ THE OUTFIT STUDIO</p><h2>YOUR FIT. <em>Your rules.</em></h2><p>One top. One bottom. Endless ways to make it yours.</p></div><div class="studio" data-studio><div class="studio-visual"><div class="studio-stamp">ESSAINT<br><span>THE ART OF EVERYDAY.</span></div><div class="studio-images"><div><img data-studio-image="top" src="{{ 'over-size-t-shirt-0.jpg' | asset_url }}" width="566" height="512" alt="Oversized T-Shirt"><span>01 / THE TOP</span></div><span class="studio-plus">+</span><div><img data-studio-image="bottom" src="{{ 'milano-striped-pants-dropping-next-week-0.png' | asset_url }}" width="1023" height="1276" alt="Milano Striped Pants"><span>02 / THE BOTTOM</span></div></div><div class="studio-caption"><span>TWO PIECES. ONE POINT OF VIEW.</span><span>01 + 02</span></div></div><form class="studio-form"><p class="eyebrow">MAKE IT A SET</p><h3>BUILD YOUR UNIFORM.</h3><div class="studio-step"><div class="step-label"><span>01</span><label for="studio-top-{{ section.id }}">CHOOSE YOUR TOP</label></div><select id="studio-top-{{ section.id }}" data-studio-product="top">{% assign tops = section.settings.tops | default: collections.all %}{% for item in tops.products %}{% assign lower = item.title | downcase %}{% if lower contains 't-shirt' %}<option value="{{ item.handle }}" {% if item.handle == 'over-size-t-shirt' %}selected{% endif %}>{{ item.title }}</option>{% endif %}{% endfor %}</select><label class="variant-label" for="studio-top-variant-{{ section.id }}">SIZE / COLOR</label><select id="studio-top-variant-{{ section.id }}" data-studio-variant="top" disabled><option>Choose a piece to see available options</option></select></div><div class="studio-step"><div class="step-label"><span>02</span><label for="studio-bottom-{{ section.id }}">CHOOSE YOUR BOTTOM</label></div><select id="studio-bottom-{{ section.id }}" data-studio-product="bottom">{% assign bottoms = section.settings.bottoms | default: collections.all %}{% for item in bottoms.products %}{% assign lower = item.title | downcase %}{% unless lower contains 't-shirt' %}<option value="{{ item.handle }}" {% if item.handle == 'milano-striped-pants-dropping-next-week' %}selected{% endif %}>{{ item.title }}</option>{% endunless %}{% endfor %}</select><label class="variant-label" for="studio-bottom-variant-{{ section.id }}">SIZE / COLOR</label><select id="studio-bottom-variant-{{ section.id }}" data-studio-variant="bottom" disabled><option>Choose a piece to see available options</option></select></div><div class="studio-total"><span>YOUR SET TOTAL</span><strong data-studio-total>—</strong></div><button class="button" data-studio-add disabled>ADD THE FULL FIT <span>↗</span></button><p class="studio-note" data-studio-message>Pick your pieces. Select your fit. We'll do the rest.</p><noscript><p>Enable JavaScript to build a set, or shop each product individually.</p></noscript></form></div><div class="preset-row"><span>NEED A STARTING POINT?</span>{% for block in section.blocks %}{% assign top = block.settings.top %}{% assign bottom = block.settings.bottom %}{% if top != blank and bottom != blank %}<button {{ block.shopify_attributes }} data-studio-preset="{{ top.handle }},{{ bottom.handle }}">{{ block.settings.title }} ↗</button>{% endif %}{% endfor %}</div></section>''',[{'type':'collection','id':'tops','label':'Tops collection'},{'type':'collection','id':'bottoms','label':'Bottoms collection'}],{'max_blocks':3,'blocks':[{'type':'outfit','name':'Suggested outfit','settings':[{'type':'text','id':'title','label':'Title','default':'The striped set'},{'type':'product','id':'top','label':'Top'},{'type':'product','id':'bottom','label':'Bottom'}]}]})
section('story','''<section class="brand-story" id="story" aria-labelledby="brand-story-title"><div class="brand-story-collage"><figure class="brand-story-photo brand-story-photo--1"><img src="{{ 'brand-story-1.jpg' | asset_url }}" alt="Pattern drafting with scissors, measuring tape and striped fabric" width="900" height="1200" loading="lazy"></figure><figure class="brand-story-photo brand-story-photo--2"><img src="{{ 'brand-story-2.jpg' | asset_url }}" alt="Selecting fabric swatches for clothing" width="900" height="1200" loading="lazy"></figure><figure class="brand-story-photo brand-story-photo--3"><img src="{{ 'brand-story-3.jpg' | asset_url }}" alt="Essaint branded bag with white linen trousers" width="900" height="1200" loading="lazy"></figure><figure class="brand-story-photo brand-story-photo--4"><img src="{{ 'brand-story-4.jpg' | asset_url }}" alt="White tee and navy pinstriped trousers styled in an armchair" width="900" height="1200" loading="lazy"></figure></div><div class="brand-story-copy"><p class="brand-story-label">Brand story</p><h2 id="brand-story-title">From Lebanon.<br>To the world.</h2><div class="brand-story-text"><p>Lebanese people have always been known for their distinctive sense of style. Essaint was created during the war from a belief in our country, its people and its potential.</p><p>We believe every Lebanese person deserves refined, well-made clothing at an accessible price. Proudly crafted in Lebanon, Essaint represents resilience, ambition and hope for what comes next.</p></div><a class="brand-story-link" href="{{ routes.all_products_collection_url }}">Explore the collection <span aria-hidden="true">&#8599;</span></a></div></section><div class="service-strip"><span>CRAFTED IN LEBANON</span><span>SHIPPING ON US OVER $100</span><span>7-DAY EASY EXCHANGES</span></div>''')
section('footer','''<footer class="footer compact-footer"><div class="footer-main"><div class="footer-brand"><a class="footer-wordmark" href="{{ routes.root_url }}" aria-label="Essaint home"><img src="{{ 'essaint-logo-light.svg' | asset_url }}" width="212" height="78" alt="Essaint" loading="lazy"></a><p>Lebanese luxury wear.</p><span>BEIRUT, LEBANON</span></div><nav class="footer-nav" aria-label="Footer navigation"><div><h3>Explore</h3><a href="{{ routes.all_products_collection_url }}">Shop all</a><a href="{{ routes.root_url }}#story">Brand story</a><a href="{{ routes.search_url }}">Search</a></div><div><h3>Help</h3><a href="/pages/contact">Contact</a><a href="https://wa.me/96171236353" target="_blank" rel="noopener">WhatsApp</a>{% for policy in shop.policies %}{% if policy.body != blank %}<a href="{{ policy.url }}">{{ policy.title }}</a>{% endif %}{% endfor %}</div></nav></div><div class="footer-bottom"><span>&copy; {{ 'now' | date: '%Y' }} ESSAINT</span><span>LEBANON / {{ cart.currency.iso_code }}</span></div></footer><nav class="mobile-dock" aria-label="Quick navigation"><a href="{{ routes.all_products_collection_url }}">SHOP</a><a href="{{ routes.all_products_collection_url }}">COLLECTION</a><button data-search>SEARCH</button><button data-cart>BAG [<span data-count>{{ cart.item_count }}</span>]</button></nav>''')
